from datetime import datetime, timezone


class BaseGenerator:
    def __init__(self, DEBUG_MODE):
        self.DEBUG_MODE = DEBUG_MODE
        # Shared guard: compute_broadcast_index helper must be emitted at most
        # once per compilation unit.
        self._broadcast_helper_emitted = False

    def cuda_header(self):
        date_str = datetime.now(timezone.utc).strftime("%Y-%m-%d")
        cuda_code = f"""
// -----------------------------------------------------------------------------
// This CUDA kernel was automatically generated by TensorLang
// TensorLang (c) 2025 David Stevens https://github.com/davro/tensor-lang
// Licensed under the GNU Lesser General Public License v3 (LGPL-3.0)
// -----------------------------------------------------------------------------
// NOTE: This file is machine-generated. Do not edit manually.
// -----------------------------------------------------------------------------
// Build date     : {date_str}

// -----------------------------------------------------------------------------

// Define FLT_MAX for CUDA device code
#ifndef FLT_MAX
#define FLT_MAX 3.402823466e+38f
#endif
// -----------------------------------------------------------------------------
"""
        if self.DEBUG_MODE:
            cuda_code += """
// TensorLang: DEBUG
#include <stdio.h>

// CUDA Error Checking Macro
#define CUDA_CHECK_ERROR() do { \\
    cudaError_t err = cudaGetLastError(); \\
    if (err != cudaSuccess) { \\
        printf("CUDA Error: %s\\n", cudaGetErrorString(err)); \\
    } \\
} while(0)
// -----------------------------------------------------------------------------
"""
        else:
            cuda_code += """
    // TensorLang: PRODUCTION

"""
        return cuda_code

    def cuda_debug(self):
        if self.DEBUG_MODE:
            return "CUDA_CHECK_ERROR();"
        return "// DEBUG DISABLED"

